/**
 * @behavior The decrypt CLI pins the STAGING manifest public key generated by the maintainer on 2026-10-26
 *           (release-channels Task 11): a valid Ed25519 key, different from the production key, byte-identical to
 *           the published value. The private half lives only in the maintainer's password manager and in the
 *           staging service's MANIFEST_SIGNING_KEY; it is never in this repository.
 * @business-rule ADR-005: staging signs with its own key, so the production private key never leaves production,
 *           and a leaked staging key cannot sign prompts production users accept.
 */
import { createPublicKey } from 'crypto';
import { describe, expect, it } from 'vitest';
import { PINNED_KEYS, PRODUCTION_MANIFEST_PUBLIC_KEY, STAGING_MANIFEST_PUBLIC_KEY } from '../src/manifest-keys.js';

const STAGING_KEY_2026_10_26 = 'MCowBQYDK2VwAyEAKLiCuK8jxJRAfaV1bqE5aSeNP+T5pG3r2jFmLb0sfqI=';

describe('the pinned staging manifest key', () => {
  it('is a valid Ed25519 public key', () => {
    const key = createPublicKey({ key: Buffer.from(STAGING_MANIFEST_PUBLIC_KEY, 'base64'), format: 'der', type: 'spki' });
    expect(key.asymmetricKeyType).toBe('ed25519');
  });

  it('differs from the production key', () => {
    expect(STAGING_MANIFEST_PUBLIC_KEY).not.toBe(PRODUCTION_MANIFEST_PUBLIC_KEY);
    expect(PINNED_KEYS.staging).not.toBe(PINNED_KEYS.production);
  });

  it('is byte-identical to the key the maintainer generated (a change here is a key rotation)', () => {
    expect(PINNED_KEYS.staging).toBe(STAGING_KEY_2026_10_26);
  });
});
